const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function ecoDecision(previous,battery){if(!battery)return previous;if(battery.charging||battery.level>=.3)return false;if(battery.level<.2)return true;return previous}
export function validSnapshot(s,now=Date.now()){return !!s&&s.version===1&&Number.isFinite(s.saved)&&s.saved<=now&&Array.isArray(s.shelters)&&s.shelters.every(p=>Number.isFinite(p.lat)&&Math.abs(p.lat)<=90&&Number.isFinite(p.lon)&&Math.abs(p.lon)<=180&&typeof p.name==='string'&&typeof p.city==='string')}
export function createSensory(ctx){
 let audio=null,source=null,gain=null,filter=null,eco=false,battery=null,haptic=false,raf=0,disposed=false,saveBusy=false;
 let snapshot=null;try{const s=JSON.parse(localStorage.getItem('ms-offline-shelters'));if(validSnapshot(s))snapshot=s;haptic=localStorage.getItem('ms-haptics')==='true'}catch{}
 const reduced=()=>matchMedia('(prefers-reduced-motion: reduce)').matches||document.documentElement.classList.contains('reduced-motion')||document.documentElement.classList.contains('light-rendering')||eco;
 function stopAudio(){source?.stop();source=null;audio?.close().catch(()=>{});audio=null;gain=null;filter=null;const b=$('#ambient-audio');if(b){b.textContent='Attiva suono ambiente';b.setAttribute('aria-pressed','false')}}
 function mood(){const w=ctx.get().weather?.current,code=w?.weather_code;return !w?'unknown':code>=51?'rain':w.wind_speed_10m>20?'wind':'calm'}
 async function startAudio(){stopAudio();const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return ctx.toast('Audio non supportato in questo browser.');try{audio=new Audio();await audio.resume();if(!audio)return;const buffer=audio.createBuffer(1,audio.sampleRate*3,audio.sampleRate),data=buffer.getChannelData(0);let last=0;for(let i=0;i<data.length;i++){last=(last+(Math.random()*2-1)*.035)/1.035;data[i]=last*3}source=audio.createBufferSource();source.buffer=buffer;source.loop=true;filter=audio.createBiquadFilter();filter.type='lowpass';gain=audio.createGain();gain.gain.value=.09;source.connect(filter);filter.connect(gain);gain.connect(audio.destination);source.start();updateAudio();$('#ambient-audio')?.setAttribute('aria-pressed','true');if($('#ambient-audio'))$('#ambient-audio').textContent='Ferma suono ambiente'}catch{stopAudio();ctx.toast('Audio non disponibile. Tocca di nuovo per riprovare.')}}
 function updateAudio(){if(filter&&audio)filter.frequency.setTargetAtTime(mood()==='rain'?1600:mood()==='wind'?650:250,audio.currentTime,.8)}
 function status(){return `<section class="card sensory-panel"><span class="eyebrow">LA TUA ATMOSFERA</span><h2>Suono, movimento e connessione</h2><div class="actions"><button id="ambient-audio" aria-pressed="${!!audio}">${audio?'Ferma suono ambiente':'Attiva suono ambiente'}</button><button id="haptic-feedback" aria-pressed="${haptic}" ${!navigator.vibrate?'disabled':''}>${haptic?'✓ ':''}Vibrazioni al tocco</button></div><p class="small">Suono sintetico ispirato al meteo disponibile, non una registrazione o un’allerta. Si interrompe cambiando schermata. ${navigator.vibrate?'Le vibrazioni dipendono dal dispositivo.':'Questo browser non espone le vibrazioni.'}</p><p id="eco-status">${eco?'Risparmio automatico attivo.':battery?'Risparmio automatico disponibile sotto il 20% di batteria.':'Batteria non leggibile: usa Grafica leggera.'} La temperatura del dispositivo non è disponibile dal sito.</p><a href="#offline">Prepara i luoghi per l’uso offline →</a></section>`}
 function offlinePage(){const old=snapshot&&Date.now()-snapshot.saved>86400000;return `<span class="eyebrow">PRIMA DI RESTARE SENZA RETE</span><h1>Luoghi salvati offline</h1><p>Salva una copia dei luoghi pubblici della community su questo dispositivo. Non comprende radar, percorsi stradali, posti liberi o nuove allerte.</p><div class="actions"><button id="save-offline" class="button">${snapshot?'Aggiorna la copia':'Salva i luoghi'}</button><button id="clear-offline" ${snapshot?'':'disabled'}>Elimina la copia</button></div><p id="offline-operation" role="status"></p>${snapshot?`<section class="notice"><b>${old?'Copia vecchia: aggiorna prima di usarla.':'Copia locale · disponibilità non verificata'}</b><p>Salvata il ${new Date(snapshot.saved).toLocaleString('it-IT')}. I luoghi potrebbero essere cambiati o essere stati rimossi.</p></section>${snapshot.shelters.length?snapshot.shelters.map(p=>`<article class="card"><h2>${esc(p.name)}</h2><p>${esc(p.city)}</p><p>${esc(p.details)}</p><p>Coordinate: ${p.lat.toFixed(5)}, ${p.lon.toFixed(5)}</p><p class="small">Accesso e sicurezza da verificare. Nessuna disponibilità in tempo reale.</p></article>`).join(''):'<section class="card">La copia non contiene luoghi: nessuno era disponibile al momento del salvataggio.</section>'}`:'<section class="card"><h2>Nessuna copia salvata</h2><p>Collegati a Internet e premi “Salva i luoghi”.</p></section>'}<p class="small">La copia può essere eliminata dal browser. Il funzionamento offline non garantisce protezione o invio di richieste di soccorso.</p>`}
 async function saveOffline(){if(saveBusy)return;saveBusy=true;const b=$('#save-offline'),out=$('#offline-operation');b.disabled=true;out.textContent='Salvataggio…';try{const r=await fetch('/api/global/shelters',{signal:AbortSignal.timeout(15000),cache:'no-store'});if(!r.ok)throw Error('Impossibile aggiornare i luoghi. La copia precedente è conservata.');const d=await r.json();const next={version:1,saved:Date.now(),shelters:(d.shelters||[]).slice(0,200).map(p=>({name:p.name,city:p.city,details:String(p.details||''),lat:p.lat,lon:p.lon}))};if(!validSnapshot(next))throw Error('Dati non validi. La copia precedente è conservata.');localStorage.setItem('ms-offline-shelters',JSON.stringify(next));snapshot=next;ctx.render();ctx.toast('Copia salvata su questo dispositivo.')}catch(e){if(out.isConnected)out.textContent=e.message;else ctx.toast(e.message)}finally{saveBusy=false;if(b.isConnected)b.disabled=false}}
 function connectivity(){document.documentElement.classList.toggle('network-offline',!navigator.onLine);const banner=$('#connection-status');if(banner){banner.hidden=navigator.onLine;banner.innerHTML='Sei offline. I dati non si aggiornano. <a href="#offline">Apri i luoghi salvati</a>'}}
 function drawDepth(){raf=0;if(reduced()||document.hidden)return;document.querySelectorAll('.story-item').forEach(card=>{const r=card.getBoundingClientRect(),relative=(r.top+r.height/2-innerHeight/2)/innerHeight;card.style.setProperty('--story-tilt',Math.max(-7,Math.min(7,relative*-9))+'deg')})}
 function onScroll(){if(!raf&&!reduced())raf=requestAnimationFrame(drawDepth)}
 function onTap(e){const button=e.target.closest('button,a');if(!button)return;if(haptic&&!document.hidden)try{navigator.vibrate?.(9)}catch{}if(reduced()||document.hidden||document.querySelectorAll('.touch-spark').length>=6)return;const r=button.getBoundingClientRect(),spark=document.createElement('i');spark.className='touch-spark';spark.setAttribute('aria-hidden','true');spark.style.left=(r.left+r.width/2)+'px';spark.style.top=(r.top+r.height/2)+'px';document.body.append(spark);spark.addEventListener('animationend',()=>spark.remove(),{once:true});setTimeout(()=>spark.remove(),700)}
 function hidden(){if(document.hidden){stopAudio();cancelAnimationFrame(raf);raf=0;document.querySelectorAll('.touch-spark').forEach(n=>n.remove())}}
 function batteryUpdate(){const next=ecoDecision(eco,battery);if(next===eco)return;eco=next;document.documentElement.classList.toggle('eco-mode',eco);if(eco)stopAudio();ctx.render()}
 navigator.getBattery?.().then(b=>{if(disposed)return;battery=b;b.addEventListener('levelchange',batteryUpdate);b.addEventListener('chargingchange',batteryUpdate);batteryUpdate()}).catch(()=>{});
 window.addEventListener('online',connectivity);window.addEventListener('offline',connectivity);window.addEventListener('scroll',onScroll,{passive:true});document.addEventListener('visibilitychange',hidden);document.addEventListener('click',onTap);
 function bind(){connectivity();document.documentElement.dataset.atmosphere=mood();updateAudio();$('#ambient-audio')?.addEventListener('click',()=>audio?stopAudio():startAudio());$('#haptic-feedback')?.addEventListener('click',e=>{haptic=!haptic;try{localStorage.setItem('ms-haptics',String(haptic))}catch{}e.currentTarget.setAttribute('aria-pressed',String(haptic));e.currentTarget.textContent=(haptic?'✓ ':'')+'Vibrazioni al tocco'});$('#save-offline')?.addEventListener('click',saveOffline);$('#clear-offline')?.addEventListener('click',()=>{try{localStorage.removeItem('ms-offline-shelters');snapshot=null;ctx.render()}catch{ctx.toast('Non riesco a eliminare la copia.')}});onScroll()}
 return {status,offlinePage,bind,savedMarkers:()=>snapshot?snapshot.shelters.map((p,i)=>({id:"saved-"+i,lat:p.lat,lon:p.lon,type:"shelter",title:p.name+" · copia del "+new Date(snapshot.saved).toLocaleDateString()})):[],isEco:()=>eco,disposeView(){stopAudio();cancelAnimationFrame(raf);raf=0},destroy(){disposed=true;stopAudio();window.removeEventListener('online',connectivity);window.removeEventListener('offline',connectivity);window.removeEventListener('scroll',onScroll);document.removeEventListener('visibilitychange',hidden);document.removeEventListener('click',onTap);battery?.removeEventListener('levelchange',batteryUpdate);battery?.removeEventListener('chargingchange',batteryUpdate)}};
}
